  "n.if-you-make-the-access.1mlyu36": {
   "t": "Když jako výchozí nastavíte přístupovou kartu, platební terminál v obchodě přestane vidět Google Wallet. Bez pomoci pak každý den přepínáte ručně tam a zpátky.",
   "en": "If you make the access card the default, the shop card machine stops seeing Google Wallet. Without help, you switch back and forth by hand every day."
  },
  "a2.1": {
   "t": "Zdarma to uděláte v nastavení telefonu:",
   "en": "You can do it for free in your phone’s settings:"
  },
  "a2.2": {
   "t": "Otevřete <b>Nastavení</b> a vyhledejte <b>bezkontaktní</b>.",
   "en": "Open <b>Settings</b> and search for <b>contactless</b>."
  },
  "a2.3": {
   "t": "Otevřete <b>Bezkontaktní platby</b>. Na některých telefonech se to jmenuje jinak, například <b>Tap and pay</b>.",
   "en": "Open <b>Contactless payments</b>. Some phones call it <b>Tap and pay</b>."
  },
  "a2.4": {
   "t": "Než dojdete ke dveřím kanceláře, vyberte přístupovou kartu.",
   "en": "Pick your access card before you reach the office door."
  },
  "a2.5": {
   "t": "Před placením znovu vyberte Google Wallet.",
   "en": "Pick Google Wallet again before you pay."
  },
  "n.if-your-phone-has-a-se.kii7nn": {
   "t": "Pokud telefon nabízí nastavení, které použije výchozí kartu, jen když není otevřená jiná platební aplikace, nejdřív ho zapněte. Některé telefony, včetně Oppo Find X9, ho nemají.",
   "en": "If your phone has a setting to use the default unless another payment app is open, turn it on first. Some phones, including the Oppo Find X9, do not have it."
  },
  "a3.1": {
   "t": "TapSwitch přepíná za vás. Přístupová karta zůstává výchozí celý den. Když otevřete Google Wallet, TapSwitch jí předá bezkontaktní platby. Když Google Wallet zavřete, vrátí se přístupová karta.",
   "en": "TapSwitch does the switching for you. Your access card stays the default all day. When you open Google Wallet, TapSwitch hands the tap over to it. When you close Google Wallet, the access card comes back."
  },
  "n.you-never-open-setting.56h87b": {
   "t": "Do Nastavení už nikdy nemusíte.",
   "en": "You never open Settings again."
  },
  "a4.1": {
   "t": "Ano. Zapněte v aplikaci <b>Reverse mode</b>. Výchozí pak zůstane Google Wallet a přístupová karta převezme jen tehdy, když je otevřená její aplikace.",
   "en": "Yes. Turn on <b>Reverse mode</b> in the app. Google Wallet then stays the default, and your access card takes over only while its app is open."
  },
  "n.in-reverse-mode-google.1go0cx7": {
   "t": "V Reverse mode je výchozí Google Wallet. Od verze 3.3.0 aplikace Access Card od Oppa nezobrazí žádné okno, když ji otevřete ze zhasnutého displeje. Jednou klepněte na domovské obrazovce na „Set it up“ a okno se neobjeví, ani když telefon právě používáte.",
   "en": "In Reverse mode, Google Wallet is the default. Since 3.3.0, Oppo’s Access Card app shows no pop-up when you open it from a dark screen. Tap “Set it up” on the home screen once, and the pop-up stays away when your phone is awake too."
  },
  "n.if-a-pop-up-still-show.xnu5bf": {
   "t": "Pokud se okno přesto objeví, nechte ho na obrazovce a přiložte telefon ke čtečce. TapSwitch už přepnul na vaši přístupovou kartu, takže se dveře otevřou.",
   "en": "If a pop-up still shows, leave it on screen and tap the reader. TapSwitch has already switched to your access card, so the door opens."
  },
  "n.tapswitch-works-on-opp.1xtd0ff": {
   "t": "TapSwitch funguje na telefonech Oppo a OnePlus s ColorOS a Androidem 16 a novějším. Je vyvíjená a denně používaná na ColorOS. Jiné telefony s ColorOS, funkcí přístupové karty a Androidem 16 a novějším by měly fungovat, ale vyzkoušené nejsou.",
   "en": "TapSwitch works on Oppo and OnePlus ColorOS phones with Android 16 or newer. It is built and used daily on ColorOS. Other ColorOS phones with the Access Card feature on Android 16 or newer should work but are untested."
  },
  "n.the-14-day-free-trial.dq7qks": {
   "t": "Během 14denní zkušební doby zdarma si to ověříte na vlastním telefonu, ještě než zaplatíte.",
   "en": "The 14-day free trial lets you find out on your own phone before you pay."
  },
  "a6.1": {
   "t": "TapSwitch nemůže číst čísla karet, platby ani záznamy o vstupech. Jen vybírá, která aplikace odpoví čtečce.",
   "en": "TapSwitch cannot read card numbers, payments or door logs. It only picks which app answers the reader."
  },
  "a6.2": {
   "t": "Jednou denně se připojí k internetu kvůli aktualizacím a nemá žádný účet, do kterého byste se přihlašovali. Před instalací si soubor můžete zdarma zkontrolovat na VirusTotal. <a href=\"/#careful\">Jak to ověřit</a>",
   "en": "It goes online once a day to check for updates, and there is no account to sign in to. You can scan the file for free on VirusTotal before you install it. <a href=\"/#careful\">How to check it</a>"
  },
  "n.one-person-makes-and-s.1nyrm85": {
   "t": "TapSwitch vytváří a prodává jeden člověk, přímo z tohoto webu. Soubor si stáhnete tady. Telefon se jednou zeptá, jestli ho povolit.",
   "en": "One person makes and sells TapSwitch, straight from this site. You download the file here. Your phone asks once whether to allow it."
  },
  "a7.2": {
   "t": "Protože nepochází z Play Store, telefon zobrazí varování. To je v pořádku.",
   "en": "Because it does not come from the Play Store, your phone shows a warning, which is normal."
  },
  "a8.1": {
   "t": "TapSwitch stojí US$7.35 jednorázově. Pokud ji nekoupíte, po skončení zkušební doby TapSwitch přestane přepínat a telefon se vrátí do původního stavu. Nic nedlužíte.",
   "en": "TapSwitch costs US$7.35, paid once. If you do not buy it, TapSwitch stops switching when the trial ends and your phone goes back to how it was. You owe nothing."
  },
  "a9.1": {
   "t": "Jsou tři. Vyberte ten, který sedí vašemu dni.",
   "en": "There are three. Pick the one that fits your day."
  },
